test('provider SEQUENCE keeps a newer shared-event revision when another account reads an older copy later',async()=>{const apple=multiAppleFixture();apple.ownerSequence=5;apple.memberSequence=1;apple.ownerTitle='Current picnic';apple.memberTitle='Old picnic';const{call}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,52).toString('base64'),ICLOUD_FETCH:apple.fetcher});await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Partner'});for(const [opts,username,calendar] of [[{},'owner@example.test',apple.calendars.owner],[{user:'member'},'bella@example.test',apple.calendars.member]]){await call('/api/icloud/connect','POST',{username,password:'synthetic-app-password'},opts);await call('/api/icloud/calendars','POST',{calendarIds:[calendar]},opts);assert.equal((await call('/api/icloud/sync','POST',{},opts)).status,200);}const events=(await call('/api/state')).data.records.filter(r=>r.kind==='calendar');assert.equal(events.some(r=>r.data.title==='Old picnic'),false);const shared=events.find(r=>r.data.title==='Current picnic');assert.equal(shared.data.calendarIds.length,2);assert.equal(shared.data.providerSequence,5);});
test('legacy eight-calendar connection and 288 records survive member-first access, owner adoption and shared UID upgrade',async()=>{const apple=multiAppleFixture();const keyBytes=Buffer.alloc(32,61),keyBase64=keyBytes.toString('base64');const{DB,call}=setup({HUB_ENCRYPTION_KEY:keyBase64,ICLOUD_FETCH:apple.fetcher});await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Partner'});await call('/api/items','POST',{kind:'source',data:{title:'iCloud',sourceId:'icloud',adapter:'icloud',schedulePaused:true,scheduleLabel:'Existing paused configuration'}});const manual=(await call('/api/items','POST',{kind:'calendar',data:{title:'Preserve manual',startAt:new Date().toISOString()}})).data.record;const aes=await crypto.subtle.importKey('raw',keyBytes,{name:'AES-GCM'},false,['encrypt']);const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('bird-family-hub:icloud:v1')},aes,new TextEncoder().encode(JSON.stringify({username:'owner@example.test',password:'legacy-app-password'})));const encrypted=JSON.stringify({v:1,iv:Buffer.from(iv).toString('base64'),ciphertext:Buffer.from(cipher).toString('base64')});const calendars=Array.from({length:8},(_,i)=>({id:i?apple.calendars.owner.replace('/owner-shared/','/extra-'+i+'/'):apple.calendars.owner,displayName:'Legacy '+i}));const lastSuccess='2026-10-29T06:00:00.000Z',now=new Date().toISOString();await DB.prepare("INSERT INTO hub_icloud(singleton,credentials,calendars,selected,status,last_attempt,last_success,revision,created_at,updated_at) VALUES(1,?,?,?,'ready',?,?,8,?,?)").bind(encrypted,JSON.stringify(calendars),JSON.stringify(calendars.map(c=>c.id)),lastSuccess,lastSuccess,now,now).run();const{hash}=await import('../server/icloud-store.ts');const currentDay=new Date();currentDay.setUTCHours(12,0,0,0);const past=new Date(currentDay);past.setUTCDate(past.getUTCDate()-100);const legacy=await Promise.all(Array.from({length:288},async(_,i)=>{const uid=i===0?'same-shared-uid':i===1?'different-owner-uid':'historical-'+i;const providerId='icloud_'+await hash(apple.calendars.owner+'\u001f'+uid+'\u001f'+'single');const recordId='icloud_'+(await hash(apple.calendars.owner+'|'+providerId)).slice(0,40);const start=i<2?currentDay:past;const end=new Date(start.getTime()+3600000);return{id:recordId,data:{title:i===0?'Shared picnic':i===1?'Same title':'Historical '+i,startAt:start.toISOString(),endAt:end.toISOString(),allDay:false,status:'confirmed',origin:'icloud',sourceId:'icloud',providerId,calendarId:apple.calendars.owner,calendarTitle:'Legacy family'}};}));await DB.batch(legacy.map(r=>DB.prepare("INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) VALUES(?,'calendar',?,1,?,?,'owner')").bind(r.id,JSON.stringify(r.data),now,now)));const member={user:'member'};assert.equal((await call('/api/icloud/connect','POST',{username:'bella@example.test',password:'member-app-password'},member)).status,200);assert.equal(await DB.prepare("SELECT COUNT(*) AS n FROM hub_records WHERE kind='calendar' AND json_extract(data,'$.origin')='icloud'").first().then(r=>r.n),288);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_icloud').first().then(r=>r.n),1);await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendars.member]},member);assert.equal((await call('/api/icloud/sync','POST',{},member)).data.error.code,'legacy_refresh_required');const adopted=await call('/api/icloud/status');assert.equal(adopted.data.username,'owner@example.test');assert.equal(adopted.data.selectedCalendarIds.length,8);assert.equal(adopted.data.lastSuccess,lastSuccess);assert.equal((await DB.prepare("SELECT credentials FROM hub_icloud_accounts WHERE user_id='owner'").first()).credentials,encrypted);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_icloud').first().then(r=>r.n),0);let state=(await call('/api/state')).data;assert.deepEqual(new Set(state.records.filter(r=>r.data.origin==='icloud').map(r=>r.id)),new Set(legacy.map(r=>r.id)));assert.ok(state.records.find(r=>r.id===manual.id));assert.equal(state.records.find(r=>r.kind==='source').data.schedulePaused,true);assert.equal(state.records.find(r=>r.kind==='source').data.scheduleLabel,'Existing paused configuration');await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendars.owner]});assert.equal((await call('/api/icloud/sync','POST',{})).status,200);state=(await call('/api/state')).data;assert.equal(state.records.find(r=>r.data.title==='Shared picnic').id,legacy[0].id);assert.equal((await call('/api/icloud/sync','POST',{},member)).status,200);state=(await call('/api/state')).data;assert.equal(state.records.filter(r=>r.data.origin==='icloud').length,289);assert.equal(state.records.filter(r=>r.data.title==='Shared picnic').length,1);assert.equal(state.records.find(r=>r.data.title==='Shared picnic').id,legacy[0].id);});
test('own and household calendar mappings require valid profiles and versions without accessing another account secret',async()=>{const apple=multiAppleFixture();const{call}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,62).toString('base64'),ICLOUD_FETCH:apple.fetcher});await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Partner'});const profile=(await call('/api/items','POST',{kind:'profile',data:{name:'Assigned person',color:'#123456'}})).data.record;for(const [opts,username,calendar] of [[{},'owner@example.test',apple.calendars.owner],[{user:'member'},'bella@example.test',apple.calendars.member]]){await call('/api/icloud/connect','POST',{username,password:'synthetic-password'},opts);await call('/api/icloud/calendars','POST',{calendarIds:[calendar]},opts);await call('/api/icloud/sync','POST',{},opts);}let owner=(await call('/api/icloud/status')).data;const own=owner.calendars[0],other=owner.householdCalendars.find(c=>!c.ownerIsMe);assert.equal((await call('/api/icloud/calendar-settings','POST',{calendarId:own.id,personId:'missing-profile',version:own.version})).status,400);assert.equal((await call('/api/icloud/calendar-settings','POST',{calendarId:own.id,personId:profile.id,version:own.version,sharedCalendarId:other.sharedCalendarId})).status,200);assert.equal((await call('/api/icloud/calendar-settings','POST',{calendarId:own.id,personId:null,version:own.version})).status,409);owner=(await call('/api/icloud/status')).data;const linked=owner.calendars[0];assert.equal(linked.sharedCalendarId,other.sharedCalendarId);const reset=await call('/api/icloud/calendar-settings','POST',{calendarId:own.id,personId:profile.id,version:linked.version,sharedCalendarId:null});assert.notEqual(reset.data.calendars[0].sharedCalendarId,other.sharedCalendarId);const metadata=await call('/api/icloud/calendar-mappings/'+other.calendarKey,'POST',{personId:profile.id,version:other.version});assert.equal(metadata.status,200);assert.equal(metadata.data.username,'owner@example.test');assert.equal(JSON.stringify(metadata.data).includes('bella@example.test'),false);assert.equal((await call('/api/icloud/status','GET',undefined,{user:'member'})).data.calendars[0].personId,profile.id);});
test('legacy adoption only captures unmanaged historical imports after another member has already synced',async()=>{const apple=multiAppleFixture(),bytes=Buffer.alloc(32,63);const{call,DB}=setup({HUB_ENCRYPTION_KEY:bytes.toString('base64'),ICLOUD_FETCH:apple.fetcher});await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Partner'});const aes=await crypto.subtle.importKey('raw',bytes,{name:'AES-GCM'},false,['encrypt']),iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('bird-family-hub:icloud:v1')},aes,new TextEncoder().encode(JSON.stringify({username:'owner@example.test',password:'legacy-password'})));const credentials=JSON.stringify({v:1,iv:Buffer.from(iv).toString('base64'),ciphertext:Buffer.from(cipher).toString('base64')}),now=new Date().toISOString();await DB.prepare("INSERT INTO hub_icloud(singleton,credentials,calendars,selected,status,last_success,revision,created_at,updated_at) VALUES(1,?,?,?,'ready',?,1,?,?)").bind(credentials,JSON.stringify([{id:apple.calendars.owner,displayName:'Owner calendar'}]),JSON.stringify([apple.calendars.owner]),now,now,now).run();const old=new Date();old.setUTCDate(old.getUTCDate()-100);await DB.prepare("INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) VALUES('historical-legacy','calendar',?,1,?,?,'owner')").bind(JSON.stringify({title:'Historical legacy event',startAt:old.toISOString(),endAt:old.toISOString(),origin:'icloud',calendarId:apple.calendars.owner,providerId:'historical-provider'}),now,now).run();const member={user:'member'};await call('/api/icloud/connect','POST',{username:'bella@example.test',password:'member-password'},member);await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendars.member]},member);assert.equal((await call('/api/icloud/sync','POST',{},member)).status,200);assert.equal((await call('/api/icloud/status')).status,200);const counts=await DB.prepare('SELECT user_id,COUNT(*) AS n FROM hub_icloud_contributions GROUP BY user_id').all();assert.equal(counts.results.find(r=>r.user_id==='owner').n,1);assert.equal(counts.results.find(r=>r.user_id==='member').n,2);assert.equal((await call('/api/state')).data.records.filter(r=>r.kind==='calendar').length,3);assert.equal((await call('/api/icloud/sync','POST',{},member)).status,200);});
test('prospective shared-calendar caps reject before persisting and stale legacy revisions cannot be adopted',async()=>{const{call,DB}=setup();await call('/api/state');const{snapshot,commitStore}=await import('../server/icloud-store.ts');const before=await snapshot(DB);const links=Array.from({length:201},(_,i)=>({calendar_key:'link-'+i,user_id:'owner',calendar_id:'https://caldav.icloud.com/'+i,shared_calendar_id:'group-'+i,display_name:'Calendar',color:null,person_id:null,selected:0,revision:1,created_at:'2026-01-01T00:00:00Z',updated_at:'2026-01-01T00:00:00Z'}));await assert.rejects(commitStore({db:DB,before,links,userId:'owner'}),e=>e.code==='icloud_capacity');const contributions=Array.from({length:4001},(_,i)=>({contribution_key:'c-'+i,user_id:'owner',calendar_id:'cal',provider_id:'p-'+i,event_key:'same-event',record_id:'same-record',data:'{}',updated_at:'2026-01-01T00:00:00Z'}));await assert.rejects(commitStore({db:DB,before,contributions,userId:'owner'}),e=>e.code==='icloud_capacity');await DB.prepare("INSERT INTO hub_icloud(singleton,credentials,calendars,selected,status,revision,created_at,updated_at) VALUES(1,'{}','[]','[]','configured',2,?,?)").bind(new Date().toISOString(),new Date().toISOString()).run();await assert.rejects(commitStore({db:DB,before,legacyRevision:1,userId:'owner'}),e=>e.code==='version_conflict');assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_icloud_calendar_links').first().then(r=>r.n),0);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_icloud_contributions').first().then(r=>r.n),0);});
